package com.vandorlabs.screen;
/** Source light entry points: only luminous screen roles query physical power, and fixed mode bypasses it. */
public final class ScreenPowerQueries {
 private ScreenPowerQueries(){}
 public static boolean lightQueriesPhysical(ScreenFamily family,int activationMode,int playback,boolean gated,boolean primaryRows,boolean secondaryRows,int channelLevel,boolean channelSignal){if(family==null||activationMode < -1||activationMode>2||playback<0||playback>2||channelLevel<0||channelLevel>15)throw new IllegalArgumentException("Screen light query");return (family==ScreenFamily.SCREEN||family==ScreenFamily.CONSOLE||family==ScreenFamily.DIAGONAL)&&(activationMode>0&&channelLevel<15||activationMode<0&&!channelSignal&&!primaryRows&&!secondaryRows&&(gated||playback==0));}
 public static boolean lightUsesGroupCache(ScreenFamily family,int activationMode,int playback,boolean gated,boolean primaryRows,boolean secondaryRows,int channelLevel,boolean channelSignal){return lightQueriesPhysical(family,activationMode,playback,gated,primaryRows,secondaryRows,channelLevel,channelSignal)&&(activationMode>0||gated);}
 public static final int SIGNAL=1,STATE=1<<1,EFFECTIVE_MODE=1<<2,SURFACE_0=1<<3,SURFACE_1=1<<4,MODE_0=1<<5,MODE_1=1<<6,SPEED_0=1<<7,SPEED_1=1<<8,OVERRIDES=1<<9,SPLIT=1<<10,PRIMARY_ARTWORK=1<<11,ANIMATION_SPEED=1<<12,ALL=(1<<13)-1;
 public static final class Context {
  public final ScreenFamily family;public final int mode,playback,channelLevel,primarySurface,secondarySurface;public final boolean gated,primaryRows,secondaryRows,channelSignal,split,small,overrides;
  public Context(ScreenFamily family,int mode,int playback,boolean gated,boolean primaryRows,boolean secondaryRows,int channelLevel,boolean channelSignal,boolean split,boolean small,boolean overrides,int primarySurface,int secondarySurface){lightQueriesPhysical(family,mode,playback,gated,primaryRows,secondaryRows,channelLevel,channelSignal);this.family=family;this.mode=mode;this.playback=playback;this.gated=gated;this.primaryRows=primaryRows;this.secondaryRows=secondaryRows;this.channelLevel=channelLevel;this.channelSignal=channelSignal;this.split=split;this.small=small;this.overrides=overrides;this.primarySurface=primarySurface;this.secondarySurface=secondarySurface;}
 }
 private static boolean mode(Context c){return c.mode>0?c.channelLevel<15:c.mode<0&&!c.channelSignal&&(c.gated||c.playback==0);}
 private static boolean surface(Context c,int slot){boolean rows=slot==0?c.primaryRows:c.secondaryRows;int raw=slot==0?c.primarySurface:c.secondarySurface;return !(raw==-4&&!rows)&&slot==c.family.activationSlot()&&c.mode>0&&c.channelLevel<15;}
 /** Exact isolated getter cost; a prepared multi-getter request can consolidate these reads. */
 public static int getterReads(Context c,int operation){if(c==null||operation<0||operation>=13)throw new IllegalArgumentException("Screen getter");boolean needed;switch(operation){case 0:case 1:needed=c.channelLevel<15;break;case 2:needed=mode(c);break;case 3:case 11:needed=surface(c,0);break;case 4:needed=surface(c,1);break;case 5:needed=(c.mode<=0||c.family.activationSlot()==0)&&mode(c);break;case 6:needed=(c.mode<=0||c.family.activationSlot()==1)&&mode(c);break;case 7:needed=c.family.activationSlot()==0&&c.mode>0&&c.channelLevel<15;break;case 8:needed=c.family.activationSlot()==1&&c.mode>0&&c.channelLevel<15;break;case 9:case 12:needed=c.mode>0&&c.channelLevel<15;break;default:needed=c.split&&c.mode>0&&c.channelLevel<15;}
  if(!needed)return 0;int slot=operation==4?1:0;boolean surface=operation==3||operation==4||operation==11,rows=slot==0?c.primaryRows:c.secondaryRows;int raw=slot==0?c.primarySurface:c.secondarySurface;return surface&&!rows&&raw!=-3&&!c.overrides&&!ScreenJoinGeometry.supports(c.family,c.small)?2:1;
 }
 public static boolean needsPhysical(Context context,int mask){if(mask<0||(mask&~ALL)!=0)throw new IllegalArgumentException("Screen getter mask");for(int i=0;i<13;i++)if((mask&(1<<i))!=0&&getterReads(context,i)>0)return true;return false;}

}
